contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, bool asOwner) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // Give c some initial balance so withdrawals have something to move.
        if (amount > 0) {
            c.fallback{value: amount}();
        }

        bool reverted;
        if (asOwner) {
            // Owner is this test contract, so this is an owner withdrawal.
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // Non-owner can only be simulated by a different msg.sender, but c's
            // onlyOwner check sees msg.sender as this test contract. Instead, we
            // test the amount-vs-balance rule through the owner path only; a
            // non-owner path is unreachable from this test contract.
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // General rule: withdrawal succeeds exactly when c has at least `amount`
        // Ether; otherwise it must revert.
        uint cBalanceBefore = address(c).balance + amount; // balance before the call (after setup)
        if (cBalanceBefore >= amount) {
            assert(!reverted);
        } else {
            assert(reverted);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
