    function run(uint amount) public payable {
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "insufficient test balance");

        // Fund c with `amount` wei so that its balance equals `amount`.
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "funding failed");

        uint balanceBefore = address(c).balance;
        bool reverted;
        try c.withdraw(amount) {
