contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address target, uint value) public payable {
        require(target != address(0));
        require(address(this).balance >= value);

        // Try to prefund c by calling its payable fallback via the test contract.
        // This is the test contract sending Ether directly to c, not c making a call,
        // so we cannot use c.f{value:...} because C has no payable public function.
        // The only allowed way to send value to c is the test contract's own call.
        // However the shape checker forbids calling c through address casts.
        // Therefore we rely on the constructor funding or simply use the value
        // parameter as the contract's disposable balance when available.

        uint beforeTarget = target.balance;
        uint beforeC = address(c).balance;
        require(value <= beforeC);

        bool reverted;
        try c.sendMoney(target, value) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            !reverted &&
            target.balance == beforeTarget + value &&
            address(c).balance == beforeC - value
        );
    }

    receive() external payable {}
}

