contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // give c some balance so withdrawAll has something to withdraw
        c{value: amount}();

        uint balBefore = address(c).balance;
        uint ownerBefore = uint(uint160(c.owner()));
        uint senderBefore = uint(uint160(msg.sender));

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;

        // owner is set once at deployment to msg.sender of the deployment transaction.
        // in the checker, the InvMutTest contract deploys c, so c.owner() == address(this),
        // not msg.sender of run().  The general rule: withdrawAll reverts iff caller != owner,
        // and on success c's balance drops to zero.
        if (senderBefore == ownerBefore && amount > 0) {
            assert(!reverted && balAfter == 0);
        } else {
            assert(reverted && balAfter == balBefore);
        }
    }

    receive() external payable {}
}

