    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        require(amount > 0);

        c.fallback{value: amount}();
        uint beforeBalance = address(c).balance;
        require(beforeBalance > 0);

        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted || (address(c).balance == 0 && address(this).balance == amount + beforeBalance));
    }

    receive() external payable {}
}

