    constructor(C _c) { c = _c; }

    function run(address target, uint value) public payable {
        require(target != address(0));
        require(address(this).balance >= value);

        c.sendMoney{value: value}(target, value);

        uint balanceBefore = address(c).balance - value;

        bool reverted;
        try c.sendMoney(target, value) { reverted = false; } catch { reverted = true; }

        uint balanceAfter = address(c).balance;

        assert(reverted == (balanceBefore < value));
        assert(reverted || balanceAfter == balanceBefore - value);
    }

    receive() external payable {}
}

