contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        // send Ether to c to make its balance nonzero
        (bool sent) = address(c).call{value: amount}("");
        require(sent);

        // now withdraw all from c
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }

        // general rule: if withdrawAll reverted, then c had zero balance before the call.
        // since we sent amount > 0, c's balance was nonzero, so it must not revert.
        // and after a successful withdrawAll, c's balance must be zero.
        assert(!reverted && address(c).balance == 0);
    }

    receive() external payable {}
}

